    ["高清", "720p"],
    ["超清", "1080p"],
    ["原始画质", "original"]
];
function get_type() {
    try {
        let varString = source.getVariable();
        if (!varString) {
            java.toast("当前未设置模式");
            return;
        }
        let currentData = JSON.parse(varString);
        let modeName = "未设置";
        for (let i = 0; i < data.length; i++) {
            if (data[i][1] === currentData.quality) {
                modeName = data[i][0];
                break;
            }
        }
        java.toast(`当前清晰度: ${modeName}`);
    } catch (e) {
        java.toast("模式数据解析错误: " + e.message);
        java.log("解析源变量出错: " + e);
    }
}
function type(mode) {
    try {
        java.log("切换模式: " + mode);
        let validMode = false;
        let modeName = "";
        let apiUrl = "";
        for (let i = 0; i < data.length; i++) {
            if (data[i][1] === mode) {
                validMode = true;
                modeName = data[i][0];
                break;
            }
        }
        if (validMode) {
            var variable = {
                "quality": mode,
                "state": true
            };
            var jsonStr = JSON.stringify(variable, null, "\t");
            source.setVariable(jsonStr);
            java.toast(`✅ 已切换到: ${modeName}`);
            java.log("设置源变量: " + jsonStr);
        } else {
            java.toast("❌ 无效模式");
        }
    } catch (e) {
        java.toast("切换模式出错: " + e.message);
        java.log("切换模式出错: " + e);
    }
}
function init() {
    try {
        let varString = source.getVariable();
        if (!varString) {
            var variable = {
                "quality": "720p",
                "state": false
            };
            var jsonStr = JSON.stringify(variable, null, "\t");
